html,
body,
#root {
  margin: 0;
  padding: 0;
  width: 100%;
  min-height: 100%;
  overflow: hidden; /* Suppress native scrollbars; Appsmith Auto-Height will handle the resizing */
  background: transparent;
}

.toggle-adjustable-container {
  display: flex;
  align-items: center;
  flex-wrap: wrap; /* Allows label to wrap below the toggle */
  width: 100%;
  padding: 0.2rem 0; /* Scaled down padding */
  background: transparent;
  box-sizing: border-box;
  gap: 0.4rem; /* Scaled down gap */
}

.adjustable-toggle-track {
  display: inline-block;
  position: relative;
  cursor: pointer;
  transition: background-color 0.3s ease;
  background: transparent;
  flex-shrink: 0;
}

.adjustable-toggle-thumb {
  position: absolute;
  background-color: #fff;
  border-radius: 50%;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.15); /* Reduced shadow spread */
  transition: left 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.adjustable-toggle-label {
  font-size: 14px; /* Scaled down from 1.125rem (~18px) to match micro UI */
  color: #1e293b;
  font-family: "Segoe UI", Inter, -apple-system, BlinkMacSystemFont, sans-serif;
  font-weight: 500;
  background: none;
  display: inline-block;
  line-height: 1.3;
  word-break: break-word; /* Ensure long words wrap if necessary */
}

.adjustable-toggle-label.hide {
  display: none !important;
}

